// ── Cryptography with Node.js built-in 'crypto' module ───────
import { createCipheriv, createDecipheriv, randomBytes, generateKeyPairSync, createDiffieHellman } from 'node:crypto';

// ── 1. AES-256-GCM: authenticated symmetric encryption ───────
function aesEncrypt(plaintext, key) {
  const iv = randomBytes(12);                       // 96-bit IV for GCM
  const cipher = createCipheriv('aes-256-gcm', key, iv);
  const encrypted = Buffer.concat([
    cipher.update(plaintext, 'utf8'),
    cipher.final(),
  ]);
  const authTag = cipher.getAuthTag();              // 16-byte integrity tag
  return { iv: iv.toString('hex'), ciphertext: encrypted.toString('hex'), authTag: authTag.toString('hex') };
}

function aesDecrypt({ iv, ciphertext, authTag }, key) {
  const decipher = createDecipheriv('aes-256-gcm', key, Buffer.from(iv, 'hex'));
  decipher.setAuthTag(Buffer.from(authTag, 'hex')); // Verifies integrity — throws if tampered
  return Buffer.concat([
    decipher.update(Buffer.from(ciphertext, 'hex')),
    decipher.final(),
  ]).toString('utf8');
}

const key = randomBytes(32);                        // 256-bit key
const encrypted = aesEncrypt('Hello, secure world!', key);
console.log('Encrypted:', encrypted);
console.log('Decrypted:', aesDecrypt(encrypted, key));

// ── 2. Diffie-Hellman key exchange simulation ─────────────────
const alice = createDiffieHellman(2048);            // Generate DH params (in practice reuse standard params)
const alicePublic = alice.generateKeys();

const bob = createDiffieHellman(alice.getPrime(), alice.getGenerator());
const bobPublic = bob.generateKeys();

const aliceSecret = alice.computeSecret(bobPublic);
const bobSecret   = bob.computeSecret(alicePublic);

console.log('Secrets match:', aliceSecret.equals(bobSecret)); // true

// ── 3. RSA key pair for hybrid encryption ─────────────────────
const { publicKey, privateKey } = generateKeyPairSync('rsa', {
  modulusLength: 2048,
  publicKeyEncoding:  { type: 'spki',  format: 'pem' },
  privateKeyEncoding: { type: 'pkcs8', format: 'pem' },
});
console.log('RSA public key (first 50 chars):', publicKey.slice(0, 50));

// ── Symmetric vs Asymmetric comparison ───────────────────────
//
// Property          │ Symmetric (AES)     │ Asymmetric (RSA/ECC)
// ──────────────────┼─────────────────────┼──────────────────────
// Keys              │ 1 shared secret     │ Public + Private pair
// Speed             │ Very fast (GB/s)    │ Slow (KB/s)
// Key size          │ 128–256 bits        │ 2048–4096 bits (RSA)
//                   │                     │ 256–521 bits (ECC)
// Key distribution  │ Hard (must share)   │ Easy (share public key)
// Use cases         │ Bulk data, TLS data │ Key exchange, signatures
//
// ── Security levels (approximate equivalence) ────────────────
const SECURITY_LEVELS = {
  '80-bit':  { symmetric: 'AES-80 (deprecated)', rsa: 'RSA-1024 (broken)', ecc: 'ECC-160' },
  '112-bit': { symmetric: 'AES-112',             rsa: 'RSA-2048',          ecc: 'ECC-224'  },
  '128-bit': { symmetric: 'AES-128',             rsa: 'RSA-3072',          ecc: 'ECC-256 (P-256, X25519)' },
  '256-bit': { symmetric: 'AES-256',             rsa: 'RSA-15360',         ecc: 'ECC-512 (P-521)'         },
};
// => ECC-256 ≈ AES-128 ≈ RSA-3072 security with far smaller key size

// ── CIA Triad in crypto primitives ───────────────────────────
const CIA = {
  Confidentiality: 'Encryption (AES-GCM, ChaCha20-Poly1305) — only authorized parties read data',
  Integrity:       'MAC / AEAD auth tag / hash — detect any modification',
  Authenticity:    'Digital signatures (ECDSA, Ed25519, RSA-PSS) — prove who created data',
};

// ── Key exchange patterns ─────────────────────────────────────
// Pattern 1: RSA key transport
//   Client generates random AES key → encrypts with server public RSA key → server decrypts with private
//   Problem: no forward secrecy (if private key later compromised, past sessions decryptable)
//
// Pattern 2: ECDHE (Ephemeral Elliptic Curve Diffie-Hellman)  ← TLS 1.3 uses this
//   Each session generates fresh ephemeral key pair → compute shared secret → derive AES key
//   Benefit: forward secrecy — past sessions safe even if long-term key compromised
